/*
* CÓDIGO DE TRANSFORMAÇÃO E ÁLGEBRA DA PLATAFORMA JAMSTACK BI-JUNIORES-ES
* 
* Este script simula o tratamento analítico pós-extração pelo Firecrawl.
*/

const rawData = $input.all();
const currentMonth = 6; // Exemplo: Junho (mês 6)
const totalMonths = 12;

// Array simulado das 28 EJs com base no DB ou extração
const ejs = []; // Aqui você preenche iterativamente no processo real.

const processedEjs = ejs.map(ej => {
  // Lógica de Alto Crescimento (Booleano)
  // AC = (Faturamento >= Meta) && (Projetos >= Meta)
  const isHighGrowth = (ej.faturamentoAlcancado >= ej.faturamentoMeta) && (ej.projetosAlcancado >= ej.projetosMeta);

  // Matemática de CSAT
  // Índice de coleta sobre os projetos avaliáveis
  const csatScore = ej.projetosAvaliados > 0 ? (ej.somaCsat / ej.projetosAvaliados) * 100 : 0;

  // Previsão Run-Rate Linear (At Risk)
  // Tendência = Média Mensal * 12
  const averageMonthlyRevenue = ej.faturamentoAlcancado / currentMonth;
  const projectedYearEndRevenue = averageMonthlyRevenue * totalMonths;
  const isAtRisk = projectedYearEndRevenue < ej.faturamentoMetaAno;

  return {
    id: ej.id,
    nome: ej.nome,
    cluster: ej.cluster,
    faturamento: {
      meta: ej.faturamentoMetaAno,
      alcancado: ej.faturamentoAlcancado,
      projetado: projectedYearEndRevenue
    },
    csat: csatScore,
    altoCrescimento: isHighGrowth,
    atRisk: isAtRisk,
    summary: "Resumo extraído via Firecrawl do PDF do Planejamento Estratégico..."
  };
});

// Convertemos para buffer para o próximo node codificar em base64
return [{ json: { result: processedEjs } }];
